library(dplyr)
library(stringr)
library(tibble)
library(readr)

# Root directory containing parameter_estimation, result_evaluation, and simulate_responses.
setwd("/root/path")

# Generated by result_evaluation/code/metrics.R.
fi_dir <- "result_evaluation/item_model_lv_summaries"
# Generated by simulate_responses/generate_responses.py; not included due to size.
analysis_dir <- "analysis"
out_file <- "shortform_additional_rebuttal.csv"

sample_sizes <- c(30, 100, 180, 400, 1000)
n_random_draws <- 30


if (file.exists(out_file)) {
  existing_results <- read_csv(out_file, show_col_types = FALSE)
} else {
  existing_results <- tibble(
    method = character(),
    benchmark = character(),
    irt = character(),
    sample_size = integer(),
    rep = integer(),
    test_length = integer(),
    kendall_cor = numeric()
  )
}

existing_keys <- paste(
  existing_results$method,
  existing_results$benchmark,
  existing_results$irt,
  existing_results$sample_size,
  existing_results$rep,
  existing_results$test_length,
  sep = "|"
)


# Read each FI file once and retain the item ordering through the top 20%.
fi_files <- list.files(
  fi_dir,
  pattern = "_FI_item\\.csv$",
  full.names = TRUE
)

fi_index <- list()

for (fi_file in fi_files) {
  file_name <- basename(fi_file)
  file_parts <- str_split(file_name, "_", simplify = TRUE)

  method <- file_parts[1]
  benchmark <- file_parts[2]
  irt <- file_parts[3]
  sample_size <- as.integer(str_extract(file_name, "(?<=N)\\d+"))

  fi_df <- read_csv(fi_file, show_col_types = FALSE)
  maximum_test_length <- floor(nrow(fi_df) * 0.20)

  for (rep_col in names(fi_df)) {
    rep <- as.integer(str_extract(rep_col, "\\d+$"))
    fi_values <- fi_df[[rep_col]]

    if (sum(is.finite(fi_values)) < maximum_test_length) next

    item_order <- order(fi_values, decreasing = TRUE, na.last = NA)[
      seq_len(maximum_test_length)
    ]

    fi_index[[length(fi_index) + 1]] <- tibble(
      method = method,
      benchmark = benchmark,
      irt = irt,
      sample_size = sample_size,
      rep = rep,
      item_order = list(item_order)
    )
  }

  rm(fi_df)
  gc()
}

fi_index <- bind_rows(fi_index)

fi_groups <- split(
  fi_index,
  list(fi_index$benchmark, fi_index$irt, fi_index$rep),
  drop = TRUE
)


# Each response matrix is shared across all methods and sample sizes in a group.
for (group_name in names(fi_groups)) {
  group_df <- fi_groups[[group_name]]

  benchmark <- group_df$benchmark[1]
  irt <- group_df$irt[1]
  rep <- group_df$rep[1]

  maximum_test_length <- length(group_df$item_order[[1]])

  test_lengths <- sort(unique(c(
    seq(100, maximum_test_length, by = 100),
    maximum_test_length
  )))

  expected_rows <- length(test_lengths) * (
    nrow(group_df) + length(sample_sizes)
  )

  existing_group_rows <- existing_results %>%
    filter(
      benchmark == !!benchmark,
      irt == !!irt,
      rep == !!rep
    ) %>%
    nrow()

  if (existing_group_rows == expected_rows) next

  resp_file <- file.path(
    analysis_dir,
    benchmark,
    irt,
    paste0("resp_sim_rep", rep, ".csv")
  )

  resp_df <- read.csv(resp_file, check.names = FALSE)
  resp_df <- tail(resp_df, 4000)

  item_df <- as.matrix(
    resp_df[
      ,
      !(names(resp_df) %in% c("sim_id", "model_id", "id")),
      drop = FALSE
    ]
  )

  rm(resp_df)
  gc()

  n_items <- ncol(item_df)
  full_score <- rowMeans(item_df)


  # FI-selected short forms for MML-EM, MCMC, PSN, and VI.
  for (condition_row in seq_len(nrow(group_df))) {
    method <- group_df$method[condition_row]
    method_label <- ifelse(method == "EM", "MML-EM", method)
    sample_size <- group_df$sample_size[condition_row]
    item_order <- group_df$item_order[[condition_row]]

    condition_keys <- paste(
      method_label,
      benchmark,
      irt,
      sample_size,
      rep,
      test_lengths,
      sep = "|"
    )

    if (all(condition_keys %in% existing_keys)) next

    short_correct <- numeric(nrow(item_df))
    previous_test_length <- 0
    condition_results <- list()

    for (test_length in test_lengths) {
      new_items <- item_order[
        (previous_test_length + 1):test_length
      ]

      short_correct <- short_correct +
        rowSums(item_df[, new_items, drop = FALSE])

      result_key <- paste(
        method_label,
        benchmark,
        irt,
        sample_size,
        rep,
        test_length,
        sep = "|"
      )

      if (!(result_key %in% existing_keys)) {
        short_score <- short_correct / test_length

        condition_results[[length(condition_results) + 1]] <- tibble(
          method = method_label,
          benchmark = benchmark,
          irt = irt,
          sample_size = sample_size,
          rep = rep,
          test_length = test_length,
          kendall_cor = cor(
            short_score,
            full_score,
            method = "kendall"
          )
        )
      }

      previous_test_length <- test_length
    }

    if (length(condition_results) > 0) {
      condition_results <- bind_rows(condition_results)

      write_csv(
        condition_results,
        out_file,
        append = nrow(existing_results) > 0,
        col_names = nrow(existing_results) == 0
      )

      existing_results <- bind_rows(existing_results, condition_results)

      existing_keys <- paste(
        existing_results$method,
        existing_results$benchmark,
        existing_results$irt,
        existing_results$sample_size,
        existing_results$rep,
        existing_results$test_length,
        sep = "|"
      )
    }
  }


  # Random short forms. Each result averages 30 random item selections.
  existing_random_rows <- existing_results %>%
    filter(
      method == "Random",
      benchmark == !!benchmark,
      irt == !!irt,
      rep == !!rep
    ) %>%
    nrow()

  if (existing_random_rows < length(test_lengths) * length(sample_sizes)) {
    random_kendall <- matrix(
      NA_real_,
      nrow = n_random_draws,
      ncol = length(test_lengths)
    )

    for (draw in seq_len(n_random_draws)) {
      random_seed <- (
        match(benchmark, c(
          "truthfulqa",
          "arc",
          "winogrande",
          "gsm8k",
          "hellaswag",
          "mmlu"
        )) * 1000000 +
          match(irt, c("1pl", "2pl", "3pl")) * 100000 +
          rep * 100 +
          draw
      )

      set.seed(random_seed)
      random_order <- sample(seq_len(n_items))

      short_correct <- numeric(nrow(item_df))
      previous_test_length <- 0

      for (test_index in seq_along(test_lengths)) {
        test_length <- test_lengths[test_index]

        new_items <- random_order[
          (previous_test_length + 1):test_length
        ]

        short_correct <- short_correct +
          rowSums(item_df[, new_items, drop = FALSE])

        short_score <- short_correct / test_length

        random_kendall[draw, test_index] <- cor(
          short_score,
          full_score,
          method = "kendall"
        )

        previous_test_length <- test_length
      }
    }

    random_results <- list()

    for (test_index in seq_along(test_lengths)) {
      test_length <- test_lengths[test_index]

      missing_sample_sizes <- sample_sizes[
        !paste(
          "Random",
          benchmark,
          irt,
          sample_sizes,
          rep,
          test_length,
          sep = "|"
        ) %in% existing_keys
      ]

      for (sample_size in missing_sample_sizes) {
        random_results[[length(random_results) + 1]] <- tibble(
          method = "Random",
          benchmark = benchmark,
          irt = irt,
          sample_size = sample_size,
          rep = rep,
          test_length = test_length,
          kendall_cor = mean(random_kendall[, test_index])
        )
      }
    }

    if (length(random_results) > 0) {
      random_results <- bind_rows(random_results)

      write_csv(
        random_results,
        out_file,
        append = nrow(existing_results) > 0,
        col_names = nrow(existing_results) == 0
      )

      existing_results <- bind_rows(existing_results, random_results)

      existing_keys <- paste(
        existing_results$method,
        existing_results$benchmark,
        existing_results$irt,
        existing_results$sample_size,
        existing_results$rep,
        existing_results$test_length,
        sep = "|"
      )
    }
  }

  rm(item_df, full_score)
  gc()

  message(paste(benchmark, irt, paste0("rep", rep), sep = " | "))
}


# ---------- Analyze the completed short-form results ----------

library(ggplot2)
library(tidyr)

shortform_results <- read_csv(out_file, show_col_types = FALSE)

benchmark_lengths <- tibble(
  benchmark = c(
    "truthfulqa",
    "arc",
    "winogrande",
    "gsm8k",
    "hellaswag",
    "mmlu"
  ),
  full_length = c(644, 844, 1045, 1306, 5711, 12508)
) %>%
  mutate(length_20_percent = floor(full_length * 0.20))

benchmark_levels <- benchmark_lengths$benchmark
benchmark_labels <- c(
  "TruthfulQA",
  "ARC-Challenge",
  "WinoGrande",
  "GSM8K",
  "HellaSwag",
  "MMLU"
)

method_levels <- c("MML-EM", "MCMC", "VI", "PSN")
sample_size_levels <- c(1000, 400, 180, 100, 30)


# Retain the same successful runs used in the parameter-recovery analyses.
# run_df.csv is generated by result_evaluation/code/Result_summary.Rmd.
eligible_runs <- read_csv(
  "result_evaluation/summary_table_all_runs/run_df.csv",
  show_col_types = FALSE
) %>%
  filter(
    exit_status == TRUE,
    is.na(failure_warning_combined)
  ) %>%
  transmute(
    method = recode(method, "EM" = "MML-EM"),
    benchmark = recode(
      benchmark,
      "TruthfulQA" = "truthfulqa",
      "ARC-Challenge" = "arc",
      "WinoGrande" = "winogrande",
      "GSM8K" = "gsm8k",
      "HellaSwag" = "hellaswag",
      "MMLU" = "mmlu"
    ),
    irt,
    sample_size = as.integer(sample_size),
    rep
  )

fi_results <- shortform_results %>%
  filter(method != "Random") %>%
  semi_join(
    eligible_runs,
    by = c("method", "benchmark", "irt", "sample_size", "rep")
  )

# Random results are repeated across sample sizes but are otherwise identical.
random_results <- shortform_results %>%
  filter(method == "Random") %>%
  distinct(
    benchmark,
    irt,
    rep,
    test_length,
    kendall_cor
  )


# Select the fixed-100 and exact-20% results.
fi_endpoint_results <- fi_results %>%
  left_join(benchmark_lengths, by = "benchmark") %>%
  mutate(
    selection_rule = case_when(
      test_length == 100 ~ "100 items",
      test_length == length_20_percent ~ "20% of items"
    )
  ) %>%
  filter(!is.na(selection_rule))

random_endpoint_results <- random_results %>%
  left_join(benchmark_lengths, by = "benchmark") %>%
  mutate(
    selection_rule = case_when(
      test_length == 100 ~ "100 items",
      test_length == length_20_percent ~ "20% of items"
    )
  ) %>%
  filter(!is.na(selection_rule))


fi_endpoint_summary <- fi_endpoint_results %>%
  group_by(
    selection_rule,
    benchmark,
    irt,
    method,
    sample_size
  ) %>%
  summarise(
    mean_kendall = mean(kendall_cor),
    .groups = "drop"
  ) %>%
  mutate(
    benchmark = factor(
      benchmark,
      levels = benchmark_levels,
      labels = benchmark_labels
    ),
    irt = factor(
      irt,
      levels = c("1pl", "2pl", "3pl"),
      labels = c("1PL", "2PL", "3PL")
    ),
    method = factor(method, levels = method_levels),
    sample_size_plot = factor(
      sample_size,
      levels = sample_size_levels
    )
  ) %>%
  arrange(
    selection_rule,
    method,
    irt,
    benchmark,
    sample_size_plot
  )

random_endpoint_summary <- random_endpoint_results %>%
  group_by(selection_rule, benchmark, irt) %>%
  summarise(
    mean_kendall = mean(kendall_cor),
    .groups = "drop"
  ) %>%
  crossing(method = method_levels) %>%
  mutate(
    benchmark = factor(
      benchmark,
      levels = benchmark_levels,
      labels = benchmark_labels
    ),
    irt = factor(
      irt,
      levels = c("1pl", "2pl", "3pl"),
      labels = c("1PL", "2PL", "3PL")
    ),
    method = factor(method, levels = method_levels)
  )


# Figure A: all benchmarks with exactly 100 selected items.
p_fixed_100 <- ggplot(
  fi_endpoint_summary %>% filter(selection_rule == "100 items"),
  aes(
    x = benchmark,
    y = mean_kendall,
    group = sample_size_plot,
    color = sample_size_plot
  )
) +
  geom_line(linewidth = 0.8) +
  geom_point(size = 1.8) +
  geom_line(
    data = random_endpoint_summary %>%
      filter(selection_rule == "100 items"),
    aes(
      x = benchmark,
      y = mean_kendall,
      group = 1,
      linetype = "Random baseline"
    ),
    inherit.aes = FALSE,
    color = "black",
    linewidth = 0.8
  ) +
  facet_grid(irt ~ method) +
  scale_color_grey(
    start = 0.8,
    end = 0.1,
    breaks = c("30", "100", "180", "400", "1000"),
    name = "Sample size"
  ) +
  scale_linetype_manual(
    values = c("Random baseline" = "dashed"),
    name = NULL
  ) +
  labs(
    title = "Fixed short-form length: 100 items",
    x = "Benchmark",
    y = "Kendall's tau: short-form vs full-benchmark score"
  ) +
  theme_bw() +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1),
    panel.grid.minor = element_blank(),
    strip.background = element_rect(fill = "grey95"),
    legend.position = "bottom"
  )

p_fixed_100

ggsave(
  "shortform_fixed_100.svg",
  plot = p_fixed_100,
  width = 7,
  height = 7
)


# Figure B: all benchmarks with exactly 20% of their items selected.
p_fixed_20_percent <- ggplot(
  fi_endpoint_summary %>% filter(selection_rule == "20% of items"),
  aes(
    x = benchmark,
    y = mean_kendall,
    group = sample_size_plot,
    color = sample_size_plot
  )
) +
  geom_line(linewidth = 0.8) +
  geom_point(size = 1.8) +
  geom_line(
    data = random_endpoint_summary %>%
      filter(selection_rule == "20% of items"),
    aes(
      x = benchmark,
      y = mean_kendall,
      group = 1,
      linetype = "Random baseline"
    ),
    inherit.aes = FALSE,
    color = "black",
    linewidth = 0.8
  ) +
  facet_grid(irt ~ method) +
  scale_color_grey(
    start = 0.8,
    end = 0.1,
    breaks = c("30", "100", "180", "400", "1000"),
    name = "Sample size"
  ) +
  scale_linetype_manual(
    values = c("Random baseline" = "dashed"),
    name = NULL
  ) +
  labs(
    title = "Fixed short-form length: 20% of benchmark items",
    x = "Benchmark",
    y = "Kendall's tau: short-form vs full-benchmark score"
  ) +
  theme_bw() +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1),
    panel.grid.minor = element_blank(),
    strip.background = element_rect(fill = "grey95"),
    legend.position = "bottom"
  )

p_fixed_20_percent

ggsave(
  "shortform_fixed_20_percent.svg",
  plot = p_fixed_20_percent,
  width = 7,
  height = 7
)


# Figure C: recovery as the absolute test length increases, by benchmark.
benchmark_plots <- list()

for (benchmark_name in benchmark_levels) {
  benchmark_label <- benchmark_labels[
    benchmark_levels == benchmark_name
  ]

  benchmark_methods <- fi_results %>%
    filter(benchmark == benchmark_name) %>%
    distinct(method) %>%
    pull(method)

  benchmark_summary <- fi_results %>%
    filter(benchmark == benchmark_name) %>%
    group_by(method, irt, sample_size, test_length) %>%
    summarise(
      mean_kendall = mean(kendall_cor),
      .groups = "drop"
    ) %>%
    mutate(
      method = factor(method, levels = method_levels),
      irt = factor(
        irt,
        levels = c("1pl", "2pl", "3pl"),
        labels = c("1PL", "2PL", "3PL")
      ),
      sample_size_plot = factor(
        sample_size,
        levels = sample_size_levels
      )
    ) %>%
    arrange(method, irt, sample_size_plot, test_length)

  benchmark_random_summary <- random_results %>%
    filter(benchmark == benchmark_name) %>%
    group_by(irt, test_length) %>%
    summarise(
      mean_kendall = mean(kendall_cor),
      .groups = "drop"
    ) %>%
    crossing(method = benchmark_methods) %>%
    mutate(
      method = factor(method, levels = method_levels),
      irt = factor(
        irt,
        levels = c("1pl", "2pl", "3pl"),
        labels = c("1PL", "2PL", "3PL")
      )
    )

  benchmark_plot <- ggplot(
    benchmark_summary,
    aes(
      x = test_length,
      y = mean_kendall,
      group = sample_size_plot,
      color = sample_size_plot
    )
  ) +
    geom_line(linewidth = 0.8) +
    geom_point(size = 1.6) +
    geom_line(
      data = benchmark_random_summary,
      aes(
        x = test_length,
        y = mean_kendall,
        group = 1,
        linetype = "Random baseline"
      ),
      inherit.aes = FALSE,
      color = "black",
      linewidth = 0.8
    ) +
    facet_grid(irt ~ method) +
    scale_color_grey(
      start = 0.8,
      end = 0.1,
      breaks = c("30", "100", "180", "400", "1000"),
      name = "Sample size"
    ) +
    scale_linetype_manual(
      values = c("Random baseline" = "dashed"),
      name = NULL
    ) +
    labs(
      title = benchmark_label,
      x = "Number of selected items",
      y = "Kendall's tau: short-form vs full-benchmark score"
    ) +
    theme_bw() +
    theme(
      panel.grid.minor = element_blank(),
      strip.background = element_rect(fill = "grey95"),
      legend.position = "bottom"
    )

  benchmark_plots[[benchmark_name]] <- benchmark_plot

  ggsave(
    paste0("shortform_", benchmark_name, "_by_length.svg"),
    plot = benchmark_plot,
    width = 7,
    height = 7
  )
}

benchmark_plots
